// The Worker entry: the OpenNext app for requests, plus the Cron Trigger
// that sweeps pending videos (wrangler.jsonc). See OpenNext's "custom
// worker" guide.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore .open-next/worker.js is generated by the OpenNext build
import { default as handler } from "./.open-next/worker.js";
import { sweepRequest } from "./src/server/cron/scheduled";

type Env = { BETTER_AUTH_URL?: string; CRON_SECRET?: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void };

const worker = {
  fetch(request: Request, env: Env, ctx: Ctx) {
    return handler.fetch(request, env, ctx);
  },

  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    const request = sweepRequest(env);
    if (!request) return console.warn(JSON.stringify({ event: "cron.skipped", reason: "CRON_SECRET or BETTER_AUTH_URL unset" }));
    const response: Response = await handler.fetch(request, env, ctx);
    if (!response.ok) throw new Error(`Sweep answered ${response.status}`);
  },
};

export default worker;
